            if grid[r][c] != bg and (r, c) not in bar_cells]

    # Each interior dot marks an offset along a border bar. Draw inward
    # rays from all parallel bars at that same offset; dots stop the rays.
    dot_set = set(dots)
    for dr, dc in dots:
        dot_color = grid[dr][dc]
        out[dr][dc] = 4
        for orient, fixed, lo, hi in bars:
            pos = dc if orient == "h" else dr
